use aap::caps::state_read;

struct Node;

fn parse(raw: &str) -> Vec<String> {
    let t = raw.trim();
    let clean = |s: &str| -> String {
        s.trim()
            .trim_matches(|c| c == '"' || c == '\'')
            .trim()
            .to_string()
    };
    if t.starts_with('[') {
        let inner = t.trim_start_matches('[').trim_end_matches(']');
        inner
            .split(',')
            .map(clean)
            .filter(|s| !s.is_empty())
            .collect()
    } else {
        t.lines()
            .map(clean)
            .filter(|s| !s.is_empty())
            .collect()
    }
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let raw = state_read::get("urls").or_else(|| state_read::get("subscriptions"));
        let urls = match raw {
            Some(r) => parse(&r),
            None => Vec::new(),
        };
        SubscriptionList { urls }
    }
}

export!(Node);
